import{G as e,W as t,n,rt as r}from"./chunks/framework.OKfwtFe7.js";var i=JSON.parse(`{"title":"行为型模式 (Behavioral Patterns)","description":"","frontmatter":{},"headers":[],"relativePath":"behavioral/overview.md","filePath":"behavioral/overview.md","lastUpdated":1790910996000}`),a={name:`behavioral/overview.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="行为型模式-behavioral-patterns" tabindex="-1">行为型模式 (Behavioral Patterns) <a class="header-anchor" href="#行为型模式-behavioral-patterns" aria-label="Permalink to “行为型模式 (Behavioral Patterns)”">​</a></h1><p><strong>主要解决的问题</strong>：对象之间如何协作和职责分配。这类模式关注算法、职责分配和对象之间的通信。 行为型模式关注对象之间的职责分配与通信方式，常见的手段包括把算法封装成可替换的对象、把请求封装成对象、以及在对象之间引入中介或观察关系，从而降低对象之间的耦合。</p><h3 id="本目录包含的模式" tabindex="-1">本目录包含的模式 <a class="header-anchor" href="#本目录包含的模式" aria-label="Permalink to “本目录包含的模式”">​</a></h3><ul><li><a href="/hello-design-patterns/behavioral/strategy">策略模式</a>：定义一系列可互换的算法，使算法的变化独立于使用它的客户端。</li><li><a href="/hello-design-patterns/behavioral/observer">观察者模式</a>：建立一对多的依赖关系，状态变化时自动通知所有观察者。</li><li><a href="/hello-design-patterns/behavioral/command">命令模式</a>：把请求封装成对象，支持参数化、排队、日志与撤销。</li><li><a href="/hello-design-patterns/behavioral/chain-of-responsibility">责任链模式</a>：让多个对象都有机会处理请求，沿链传递直到被处理。</li><li><a href="/hello-design-patterns/behavioral/mediator">中介者模式</a>：用中介对象封装一组对象之间的交互，避免对象直接相互引用。</li><li><a href="/hello-design-patterns/behavioral/iterator">迭代器模式</a>：顺序访问聚合对象中的元素，而不暴露其内部表示。</li><li><a href="/hello-design-patterns/behavioral/template-method">模板方法模式</a>：定义算法骨架，把某些步骤延迟到子类实现。</li><li><a href="/hello-design-patterns/behavioral/state">状态模式</a>：对象在内部状态改变时改变自己的行为。</li><li><a href="/hello-design-patterns/behavioral/memento">备忘录模式</a>：在不破坏封装性的前提下保存并恢复对象的内部状态。</li><li><a href="/hello-design-patterns/behavioral/snapshot">快照模式</a>：备忘录模式的另一种常见叫法，侧重快照的创建与恢复。</li><li><a href="/hello-design-patterns/behavioral/interpreter">解释器模式</a>：为简单语言定义文法表示，并提供解释句子的解释器。</li><li><a href="/hello-design-patterns/behavioral/visitor">访问者模式</a>：在不改变元素类的前提下，为对象结构增加新的操作。</li><li><a href="/hello-design-patterns/behavioral/callback">回调模式</a>：把处理逻辑作为回调传入，在异步操作完成或事件发生时被调用。</li><li><a href="/hello-design-patterns/behavioral/dsl">领域特定语言（DSL）</a>：针对特定领域设计专用语言或语言扩展，提高表达效率。</li></ul><h3 id="选用建议" tabindex="-1">选用建议 <a class="header-anchor" href="#选用建议" aria-label="Permalink to “选用建议”">​</a></h3><ul><li>算法需要可替换时用策略；行为随状态变化时用状态。</li><li>一对多的状态通知用观察者；请求的处理者不确定时用责任链。</li><li>需要撤销、排队、记录日志的请求用命令；需要保存历史状态用备忘录。</li><li>遍历逻辑与容器实现分离用迭代器；稳定结构上频繁新增操作用访问者。</li></ul>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};